package aws.sdk.kotlin.gradle.dokka.markdown

import org.gradle.kotlin.dsl.dependencies
import org.jetbrains.dokka.gradle.formats.DokkaFormatPlugin
import org.jetbrains.dokka.gradle.internal.InternalDokkaGradlePluginApi

/**
 * Registers a `markdown` Dokka publication which renders API docs as GitHub Flavored Markdown (GFM) using Dokka's
 * `gfm-plugin`. The publication is generated by `dokkaGeneratePublicationMarkdown` into `build/dokka/markdown` and is
 * also run by the `dokkaGenerate` lifecycle task alongside any other configured formats (e.g., HTML).
 *
 * Aggregating projects merge their modules' output with `gfm-template-processing-plugin`. It is only added to the
 * publication plugin classpath because applying it while generating a single module replaces that module's pages
 * with an all-modules index.
 *
 * Plugin versions are aligned with the Dokka engine version used by the consuming build. This plugin extends internal
 * Dokka Gradle plugin APIs and is built against a specific Dokka version.
 */
@OptIn(InternalDokkaGradlePluginApi::class)
abstract class DokkaMarkdownPlugin : DokkaFormatPlugin(formatName = "markdown") {
    override fun DokkaFormatPluginContext.configure() {
        project.dependencies {
            dokkaPlugin(dokka("gfm-plugin"))
        }

        formatDependencies.dokkaPublicationPluginClasspathApiOnly.dependencies.addLater(
            dokkaExtension.dokkaEngineVersion.map { version ->
                project.dependencies.create("org.jetbrains.dokka:gfm-template-processing-plugin:$version")
            },
        )
    }
}
